package net.civeira.phylax.feature.observe.observedalert.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class ProblemKeyVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property problem key of observed alert ")
  void test_problem_key_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> ProblemKeyVO.tryFrom(null));
    Assertions.assertEquals("one", ProblemKeyVO.from("one").getProblemKey());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> ProblemKeyVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", ProblemKeyVO.from("one").toString());
  }
}
